create or replace function public.increment_ai_usage()\nreturns public.ai_usage\nlanguage plpgsql\nset search_path = public\nas $$\ndeclare result public.ai_usage;\nbegin\n  if auth.uid() is null then raise exception 'AUTH_REQUIRED'; end if;\n  insert into public.ai_usage(user_id, usage_date, request_count) values (auth.uid(), current_date, 1)\n  on conflict (user_id, usage_date) do update set request_count = public.ai_usage.request_count + 1, updated_at = now()\n  where public.ai_usage.request_count < 10\n  returning * into result;\n  if result.user_id is null then raise exception 'AI_DAILY_LIMIT_REACHED'; end if;\n  return result;\nend;\n$$;\nrevoke all on function public.increment_ai_usage() from public, anon;\ngrant execute on function public.increment_ai_usage() to authenticated;\n